mapper.sql:
WHERE orders.status > 0

    AND (
    orders.order_code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND orders.order_date >= #{filter.dateFrom}


    AND orders.order_date <= #{filter.dateTo}


    AND orders.type = #{filter.type}


    AND orders.customer_id = #{filter.organizationId}


    AND orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})


    AND orders.is_close = #{filter.isClose}


    AND orders.is_approve = #{filter.isApprove}


    AND orders.created_by = #{filter.createdBy}


    AND orders.is_none_vat = #{filter.filterBy}




        AND sales_orders.delivery_id IS NOT NULL AND sales_orders.status = 2


        AND sales_orders.delivery_id IS NULL AND sales_orders.status > 0

mapper.select:
SELECT orders.id AS id, orders.order_date AS soDate, orders.order_code AS soCode, CONCAT(customers.name_kh, ' (', customers.name, ')') AS organizationName
GROUP BY orders.order_code
LIMIT #{filter.page}, #{filter.rowsPerPage}
